private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        throw new IllegalArgumentException("node cannot be null or node must have a left child for a right rotation");
    }

    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;

    node.height = Math.max(node.leftHeight(), node.rightHeight()) + 1;
    newParent.height = Math.max(newParent.leftHeight(), node.height) + 1;

    return newParent;
}
