private int parseEndOfLine(String headerPart, int end) {
    // Check for null or empty input
    if (headerPart == null || headerPart.isEmpty()) {
        throw new IllegalArgumentException("Header part cannot be null or empty");
    }
    // Check if end index is within valid range
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("End index is out of bounds");
    }
    // Iterate from the end index towards the beginning to find the "\r\n" sequence
    for (int i = end; i > 0; i--) {
        if (headerPart.charAt(i) == '\n' && headerPart.charAt(i - 1) == '\r') {
            return i - 1; // Return the index of the "\r" character
        }
    }
    // If no "\r\n" sequence is found, return -1
    return -1;
}
