public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {

    // Check if resultMap is empty
    if (resultMap.isEmpty()) {
        throw new IllegalArgumentException("resultMap cannot be empty");
    }

    // Get vertices from resultMap
    Set<V> vertices = resultMap.values();

    // Check if number of vertices is even, required for bipartite graph
    if (vertices.size() % 2 != 0) {
        throw new IllegalArgumentException("Number of vertices must be even for a bipartite graph");
    }

    // Create two partitions of vertices
    Set<V> partition1 = new HashSet<>(vertices.size() / 2);
    Set<V> partition2 = new HashSet<>(vertices.size() / 2);

    // Distribute vertices between two partitions
    int partitionIndex = 0;
    for (V vertex : vertices) {
        if (partitionIndex % 2 == 0) {
            partition1.add(vertex);
        } else {
            partition2.add(vertex);
        }
        partitionIndex++;
    }

    // Add edges between the two partitions
    for (V v1 : partition1) {
        for (V v2 : partition2) {
            E edge = target.addEdge(v1, v2);
            if (edge == null) {
                throw new RuntimeException("Failed to add edge between " + v1 + " and " + v2);
            }
        }
    }

    // Print the number of edges added
    System.out.println("Number of edges added: " + target.edgeSet().size());
