public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Parameters cannot be null");
    }

    // Serialize the message using the provided schema and buffer
    byte[] data = schema.writeTo(buffer, message);
    int dataSize = data.length;

    // Write the size of the message as an integer (4 bytes) followed by the message data
    out.write(dataSize >>> 24);
    out.write((dataSize >>> 16) & 0xFF);
    out.write((dataSize >>> 8) & 0xFF);
    out.write(dataSize & 0xFF);
    out.write(data);

    // Clear the buffer
    buffer.clear();

    return dataSize + 4; // The size includes the length prefix (4 bytes)
}
