 * @return the size of the message
 */
public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Step 1: Serialize the message to a byte array
    byte[] messageBytes = schema.encode(message, buffer);

    // Step 2: Write the length of the message to the output stream
    int length = messageBytes.length;
    out.write(length >>> 24);
    out.write((length >>> 16) & 0xFF);
    out.write((length >>> 8) & 0xFF);
    out.write(length & 0xFF);

    // Step 3: Write the message bytes to the output stream
    out.write(messageBytes);

    // Step 4: Return the total size of the message
    return length + 4; // Length of the message + 4 bytes for the length prefix
}
