public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("message, schema, and buffer cannot be null");
    }

    int messageSize = schema.getSerializedSize(message);
    if (messageSize > ByteBuffer.MAX_VALUE) {
        throw new IOException("Message size exceeds maximum allowed size");
    }

    byte[] messageBytes = schema.toByteArray(message, buffer);
    byte[] sizeBytes = ByteBuffer.allocate(4).putInt(messageSize).array();

    out.write(sizeBytes);
    out.write(messageBytes);
    return messageSize;
}
