public synchronized void send(final String message) {
    // Check if the message is null or empty
    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Message cannot be null or empty");
    }

    // Retrieve the list of clients to send the message to
    List<String> clients = getClientList();

    // Check if there are any clients to send the message to
    if (clients == null || clients.isEmpty()) {
        return;
    }

    // Send the message to each client
    for (String client : clients) {
        try {
            // Create a telnet output stream for the client
            TelnetOutputStream outputStream = new TelnetOutputStream(client);

            // Write the message to the output stream
            outputStream.write(message.getBytes());

            // Flush the output stream to ensure the message is sent
            outputStream.flush();

            // Close the output stream
            outputStream.close();
