static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract year, month, and day from the time bucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Adjust the day based on dayStep
        day = (day + dayStep - 1) / dayStep * dayStep;

        // Ensure the day is within the valid range for the month
        if (day > monthDays(year, month)) {
            day = monthDays(year, month);
        }

        // Ensure the month is within the valid range for the year
        if (month > 12) {
            month = 12;
        }

        // Reconstruct the time bucket
        return (year * 10000L) + (month * 100L) + day;
    } catch (ArithmeticException e) {
        // Handle potential arithmetic issues (e.g., division by zero)
        return -1;
    } catch (Exception e) {
        // Handle other potential exceptions
        return -1;
    }
}

// Helper method to determine the number of days in a given month
private static int monthDays(int year, int month) {
    switch (month) {
        case 2:
            return isLeapYear(year) ? 29 : 28;
        case 4:
        case 6:
        case 9:
        case 11:
            return 30;
        default:
            return 31;
    }
}

// Helper method to determine if a given year is a leap year
private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}
