static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract the year, month, and day from the time bucket
        int year = (int) (timeBucket / 10000);
        int month = (int) (timeBucket / 100 % 100);
        int day = (int) (timeBucket % 100);

        // Adjust the day based on the dayStep
        if (dayStep == 0) {
            return timeBucket;
        } else if (dayStep < 0) {
            day -= dayStep;
        } else {
            day += dayStep;
        }

        // Ensure the day is valid
        if (day < 1) {
            // If the day is negative, move to the end of the previous month
            do {
                if (month == 1) {
                    month = 12;
                    year--;
                } else {
                    month--;
                }
                day += daysInMonth(year, month);
            } while (day < 1);
        } else if (day > daysInMonth(year, month)) {
            // If the day is beyond the end of the month, move to the start of the next month
            do {
                if (month == 12) {
                    month = 1;
                    year++;
                } else {
                    month++;
                }
                day -= daysInMonth(year, month);
            } while (day > daysInMonth(year, month));
        }

        // Reconstruct the time bucket with the adjusted day
        return year * 10000 + month * 100 + day;
    } catch (Exception e) {
        // Handle any exceptions and return a default value or throw a custom exception
        e.printStackTrace();
        return -1;
    }
}

private static int daysInMonth(int year, int month) {
    return switch (month) {
        case 1, 3, 5, 7, 8, 10, 12 -> 31;
        case 4, 6, 9, 11 -> 30;
        default -> isLeapYear(year) ? 29 : 28;
    };
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}
