    // Check if index is within the bounds of the string
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index out of bounds: " + index);
    }

    // Check if length is non-negative and does not exceed the remaining length of the string
    if (len < 0 || len > str.length() - index) {
        throw new IllegalArgumentException("Length out of bounds: " + len);
    }

    int count = 0;
    int end = index + len;

    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            count += 1;  // 7-bit ASCII: one byte
        } else if (c <= 0x7FF) {
            count += 2;  // 11-bit Unicode: two bytes
        } else if (c <= 0xFFFF) {
            count += 3;  // 16-bit Unicode: three bytes
        } else {
            count += 4;  // 21-bit Unicode: four bytes
        }
    }

    return count;
}
