private static String performVariableSubstitution(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (value.charAt(i) == '${' && i < value.length() - 1) {
            int endIndex = value.indexOf('}', i);
            if (endIndex == -1) {
                // Invalid variable syntax
                result.append(value, i, value.length());
                break;
            }
            String propertyName = value.substring(i + 2, endIndex);
            String propertyValue = props.getProperty(propertyName);
            if (propertyValue != null) {
                result.append(propertyValue);
            } else {
                // Variable not found, append the original substring
                result.append(value, i, endIndex + 1);
            }
            i = endIndex + 1;
        } else {
            result.append(value.charAt(i));
            i++;
        }
    }
    return result.toString();
}
