private static String substituteVariables(String value, Properties props) {
    int startIndex = 0;
    StringBuilder result = new StringBuilder();

    while (startIndex < value.length()) {
        int openingIndex = value.indexOf('${', startIndex);
        if (openingIndex == -1) {
            result.append(value.substring(startIndex));
            break;
        }

        result.append(value, startIndex, openingIndex);
        int closingIndex = value.indexOf('}', openingIndex);
        if (closingIndex == -1) {
            throw new IllegalArgumentException("Unmatched '${' found in value: " + value);
        }

        String variableKey = value.substring(openingIndex + 2, closingIndex);
        String variableValue = props.getProperty(variableKey);
        if (variableValue != null) {
            result.append(variableValue);
        } else {
            // If the variable is not found, leave it as is
            result.append("${").append(variableKey).append("}");
        }

        startIndex = closingIndex + 1;
    }

    return result.toString();
}
