    char currentChar;
    int popCount = 0;

    for (int i = 0; i < descriptor.length(); i++) {
        currentChar = descriptor.charAt(i);

        // Check for primitive types and array types
        if (currentChar == 'B' || currentChar == 'C' || currentChar == 'D' || currentChar == 'F' || currentChar == 'I' || currentChar == 'J' || currentChar == 'S' || currentChar == 'Z' || currentChar == '[') {
            popCount++;
        }
        // Check for reference types and method descriptors
        else if (currentChar == 'L' || currentChar == '(') {
            int matchingParenthesis = 1;
            i++; // Move to the next character after 'L' or '('

            // Count matching parentheses
            while (matchingParenthesis > 0 && i < descriptor.length()) {
                currentChar = descriptor.charAt(i);
                if (currentChar == '(') {
                    matchingParenthesis++;
                } else if (currentChar == ')') {
                    matchingParenthesis--;
                }
                i++;
            }

            // Adjust i to point to the character after the closing parenthesis
            i--;
            popCount++;
        } else {
            throw new IllegalArgumentException("Invalid descriptor character: " + currentChar);
        }
    }

    // Step 4: Pop the appropriate number of elements from the stack
    for (int i = 0; i < popCount; i++) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        } else {
