public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean escapeNext = false;

    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);

        if (escapeNext) {
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append '\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(ch);
                    break;
            }
            escapeNext = false;
        } else if (ch == '\\') {
            escapeNext = true;
        } else {
            sb.append(ch);
        }
    }

    return sb.toString();
}
