            return null;
        }

        // Recursively remove inactive nodes from left and right subtrees
        node.left = removeInactive(node.left);
        node.right = removeInactive(node.right);

        // If the current node is inactive and has no active children, remove it
        if (!node.isActive && node.left == null && node.right == null) {
