private int removeInactiveNodesRecursively(CategoryNode node){
    // Initialize a counter to keep track of removed nodes at the current level
    int removedNodes = 0;

    // Iterate through the current node's children
    for (Iterator<CategoryNode> it = node.getChildren().iterator(); it.hasNext();){
        CategoryNode child = it.next();

        // Recursively remove inactive nodes from the child
        removedNodes += removeInactiveNodesRecursively(child);

        // If the child is inactive, remove it from the current node's list of children
        if (!child.isActive()){
            it.remove();
            removedNodes++;
        }
    }

    // Return the total number of removed nodes at the current level
    return removedNodes;
