    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer");
    }

    // Base case: factorial of 0 is 1
    if (n == 0) {
        return 1;
    }

    // Calculate factorial iteratively to avoid stack overflow
    long result = 1;
    for (int i = 1; i <= n; i++) {
        result *= i;
    }

    return result;
}
