        throw new IllegalArgumentException("Start and stop nodes cannot be null");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.isDone()) {
        Node currentNode = circulator.getNode();
        if (predicate.test(currentNode)) {
            return circulator;
        }
        if (currentNode == stop) {
            return circulator;
        }
        circulator.next();
    }

    throw new NoSuchElementException("Node satisfying the predicate or stop node not found");
