    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    try {
        List<E> path = new ArrayList<>(tour);
        path.sort(Comparator.comparing(t -> graphConnectingOrder(t, graph)));

        return new DefaultGraphPath<>(graph, path);

    } catch (Exception e) {
        throw new RuntimeException("Error converting edge set to path", e);
    }
}

private int graphConnectingOrder(E edge, Graph<V, E> graph) {
    V startVertex = edgeSource(edge, graph);
    V endVertex = edgeTarget(edge, graph);

    // Assuming each edge has a weight and we want to sort by the weight of the outgoing edges from the start vertex
    int outgoingEdgesWeight = graph.edgesOf(startVertex).stream()
            .mapToInt(e -> edgeWeight(e, graph))
            .sum();

    return outgoingEdgesWeight;
}

private V edgeSource(E edge, Graph<V, E> graph) {
    if (edge instanceof DefaultEdge) {
        return (V) ((DefaultEdge) edge).getSource();
    } else {
        return graph.getEdgeSource(edge);
    }
}

private V edgeTarget(E edge, Graph<V, E> graph) {
    if (edge instanceof DefaultEdge) {
        return (V) ((DefaultEdge) edge).getTarget();
    } else {
        return graph.getEdgeTarget(edge);
    }
}

