import java.util.Iterator;
import java.util.NoSuchElementException;

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) throws NoSuchElementException {
    if (tour == null || tour.isEmpty()) {
        throw new NoSuchElementException("Tour set cannot be null or empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V startVertex = firstEdge.getSource();
    if (!iterator.hasNext()) {
        return new DefaultGraphPath<>(graph, startVertex, startVertex, 0, Collections.emptyList());
    }

    List<E> edges = new ArrayList<>();
    edges.add(firstEdge);
    V currentVertex = firstEdge.getTarget();
    while (iterator.hasNext()) {
        E nextEdge = iterator.next();
        if (!Objects.equals(nextEdge.getSource(), currentVertex)) {
            throw new IllegalArgumentException("Tour edges are not in a linear sequence");
        }
        edges.add(nextEdge);
        currentVertex = nextEdge.getTarget();
    }

    return new DefaultGraphPath<>(graph, startVertex, currentVertex, edges.stream().mapToLong(e -> graph.getEdgeWeight(e)).sum(), edges);
}
