    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.size() == 0) {
        return new Walk<V,E>(graph, Collections.emptyList());
    }

    // Create a list to hold the vertices of the path
    List<V> vertices = new ArrayList<>();
    vertices.add(edgeList.get(0).getTarget());

    // Traverse the edges to build the vertices list
    for (int i = 0; i < edgeList.size(); i++) {
        E edge = edgeList.get(i);
        V currentVertex = vertices.get(vertices.size() - 1);
        V nextVertex = edge.getSource();

        if (!currentVertex.equals(nextVertex)) {
            vertices.add(nextVertex);
        }
    }

    // Create and return the graph path
    return new Walk<V,E>(graph, edgeList, vertices);
}
