private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSumList = new ArrayList<>(bounds.size());
    long totalSum = 0;
    long currentSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (bounds.get(i) < 0) {
            throw new IllegalArgumentException("Negative values are not allowed in bounds list.");
        }
        currentSum += bounds.get(i);
        suffixSumList.add(0, (int) currentSum);
    }

    totalSum = currentSum;

    return new Pair<>(suffixSumList, totalSum);
}
