public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    for (int i = 0; i < n; i++) {
        totalSum += bounds.get(i);
        suffixSum.add(totalSum);
    }

    // Reverse the suffix sum list to get the correct suffix sum
    Collections.reverse(suffixSum);

    return Pair.with(suffixSum, totalSum);
}
