    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;

    // Calculate the entire sum of the list
    for (int num : bounds) {
        totalSum += num;
    }

    // Compute suffix sums
    long currentSum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSum += bounds.get(i);
        suffixSumList.add((int) currentSum);
    }

    // Reverse the list to maintain the correct order
    Collections.reverse(suffixSumList);

    return new Pair<>(suffixSumList, totalSum);
}
