    List<Pair<List<Pair<Integer,Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edgeSet()) {
        Set<Integer> neighborhood = new HashSet<>();
        for (Integer sourceVertex : graph.getEdgeSource(edge)) {
            for (Integer neighbor : graph.neighbors(sourceVertex)) {
                if (!neighborhood.contains(neighbor)) {
                    neighborhood.add(neighbor);
                }
            }
        }
        for (Integer targetVertex : graph.getEdgeTarget(edge)) {
            for (Integer neighbor : graph.neighbors(targetVertex)) {
                if (!neighborhood.contains(neighbor)) {
                    neighborhood.add(neighbor);
                }
            }
        }
        List<Pair<Integer, Integer>> separators = findMinimalseparatorsForEdge(graph, edge);
        globalSeparatorList.add(new Pair<>(separators, edge));
    }

    return globalSeparatorList;
}

private List<Pair<Integer, Integer>> findMinimalseparatorsForEdge(Graph<Integer, E> graph, Edge<E> edge) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    Set<Integer> sourceNeighborhood = new HashSet<>(graph.neighbors(graph.getEdgeSource(edge)));
    Set<Integer> targetNeighborhood = new HashSet<>(graph.neighbors(graph.getEdgeTarget(edge)));

    for (Integer vertex : sourceNeighborhood) {
        if (!targetNeighborhood.contains(vertex)) {
            Set<Integer> intersection = new HashSet<>(sourceNeighborhood);
            intersection.retainAll(graph.neighbors(vertex));
            if (intersection.size() == 1) {
                separators.add(new Pair<>(vertex, graph.getEdgeSource(edge)));
            }
        }
    }

    for (Integer vertex : targetNeighborhood) {
        if (!sourceNeighborhood.contains(vertex)) {
            Set<Integer> intersection = new HashSet<>(targetNeighborhood);
            intersection.retainAll(graph.neighbors(vertex));
            if (intersection.size() == 1) {
                separators.add(new Pair<>(vertex, graph.getEdgeTarget(edge)));
            }
        }
    }

    return separators;
}
