private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(Graph<Integer, E> graph) throws NullPointerException {
    if (graph == null) {
        throw new NullPointerException("The graph cannot be null");
    }

    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.edgeSet()) {
        Integer source = graph.getEdgeSource(edge);
        Integer target = graph.getEdgeTarget(edge);

        if (source == null || target == null) {
            throw new NullPointerException("Edge source or target cannot be null");
        }

        List<Pair<Integer, Integer>> minimalSeparators = findMinimalSeparators(graph, source, target);

        globalSeparatorList.add(new Pair<>(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

private List<Pair<Integer, Integer>> findMinimalSeparators(Graph<Integer, E> graph, Integer source, Integer target) {
    List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();

    // Find all vertices except source and target
    Set<Integer> remainingVertices = new HashSet<>(graph.vertexSet());
    remainingVertices.remove(source);
    remainingVertices.remove(target);

    for (Integer v : remainingVertices) {
        List<Integer> path = findPath(graph, source, v, target);
        if (path != null) {
            minimalSeparators.add(new Pair<>(source, v));
            minimalSeparators.add(new Pair<>(v, target));
        }
    }

    return minimalSeparators;
}

private List<Integer> findPath(Graph<Integer, E> graph, Integer start, Integer end, Integer last) {
    Queue<List<Integer>> queue = new LinkedList<>();
    Set<Integer> visited = new HashSet<>();

    List<Integer> initialPath = new ArrayList<>();
    initialPath.add(start);
    queue.add(initialPath);

    while (!queue.isEmpty()) {
        List<Integer> currentPath = queue.poll();
        Integer currentVertex = currentPath.get(currentPath.size() - 1);

        if (currentVertex == end) {
            return currentPath;
        }

        if (!visited.contains(currentVertex)) {
            visited.add(currentVertex);

            for (Edge<E> edge : graph.edgesOf(currentVertex)) {
                Integer neighbor = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);

                if (neighbor != last && !visited.contains(neighbor)) {
                    List<Integer> newPath = new ArrayList<>(currentPath);
                    newPath.add(neighbor);
                    queue.add(newPath);
                }
            }
        }
    }

    return null;
}
