        int u = edge.getValue0();
        int v = edge.getValue1();
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

        for (Integer neighbor : graph.getNeighbors(u)) {
            if (neighbor != v) {
                for (Integer otherNeighbor : graph.getNeighbors(v)) {
                    if (otherNeighbor != u && otherNeighbor != neighbor) {
                        localSeparatorList.add(new Pair<>(neighbor, otherNeighbor));
                    }
                }
            }
        }

        globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
    }

    return globalSeparatorList;
