public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check if the table or pane is null
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table or pane cannot be null");
    }

    // Check if the specified row is within the valid range
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index is out of bounds");
    }

    // Select the specified row
    ListSelectionModel selectionModel = table.getSelectionModel();
    selectionModel.setSelectionInterval(row, row);

    // Scroll the table to the newly selected row
    Rectangle rowBounds = table.getCellRect(row, 0, true);
    if (rowBounds != null) {
        pane.getViewport().scrollRectToVisible(rowBounds);
    }

    // Repaint the table after a short delay
    SwingUtilities.invokeLater(() -> {
        try {
            Thread.sleep(100); // delay for 100 milliseconds
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        table.repaint();
    });
}
