/**
 * Puts an int into this byte vector. The byte vector is automatically enlarged if necessary.
 * @param intValue an int.
 * @return this byte vector.
 */
public ByteVector putInt(final int intValue) {
    if (intValue < 0 || intValue > 255) {
        throw new IllegalArgumentException("intValue must be between 0 and 255");
    }
    ensureCapacity(4);
    intToByteArray(intValue);
    return this;
}

private void ensureCapacity(int additionalCapacity) {
    if (capacity - writeIndex < additionalCapacity) {
        int newCapacity = Math.max(capacity, (int) (capacity * 1.5f));
        byte[] newElements = new byte[newCapacity];
        System.arraycopy(elements, 0, newElements, 0, writeIndex);
        elements = newElements;
        capacity = newCapacity;
    }
}

private void intToByteArray(int value) {
    elements[writeIndex++] = (byte) (value >>> 24);
    elements[writeIndex++] = (byte) (value >>> 16);
    elements[writeIndex++] = (byte) (value >>> 8);
    elements[writeIndex++] = (byte) value;
}
```

Note: The `ByteVector` class should have `capacity`, `writeIndex`, and `elements` fields to manage the byte vector's state.

