public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths
    String normalizedPath = path.endsWith("/") ? path : path + "/";
    String normalizedRelativePath = relativePath.startsWith("/") ? relativePath : "/" + relativePath;

    // Split the paths into components
    String[] components = normalizedPath.split("/");
    String[] relativeComponents = normalizedRelativePath.split("/");

    // Apply the relative path
    for (String component : relativeComponents) {
        if ("..".equals(component)) {
            // Go up one directory
            if (components.length > 1) {
                components = Arrays.copyOfRange(components, 0, components.length - 1);
            }
        } else if (!component.isEmpty()) {
            // Add the component to the path
            components = Arrays.copyOf(components, components.length + 1);
            components[components.length - 1] = component;
        }
    }

    // Join the components back into a single path
    return String.join("/", components);
}
