public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Split the paths into arrays
    String[] pathArray = path.split("/");
    String[] relativePathArray = relativePath.split("/");

    // Process the relative path
    int i = 0;
    while (i < relativePathArray.length && !relativePathArray[i].isEmpty()) {
        if (relativePathArray[i].equals("..")) {
            // Move up one directory
            if (pathArray.length > 1) {
                pathArray = java.util.Arrays.copyOf(pathArray, pathArray.length - 1);
            }
        } else if (!relativePathArray[i].equals(".")) {
            // Move into a subdirectory
            pathArray = java.util.Arrays.copyOf(pathArray, pathArray.length + 1);
            pathArray[pathArray.length - 1] = relativePathArray[i];
        }
        i++;
    }

    // Reconstruct the full path
    StringBuilder fullPath = new StringBuilder();
    for (String segment : pathArray) {
        if (fullPath.length() > 0) {
            fullPath.append("/");
        }
        fullPath.append(segment);
    }

    return fullPath.toString();
}
