/**
 * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
 * @param path the path to start from (usually a full file path)
 * @param relativePath the relative path to apply(relative to the full file path above)
 * @return the full file path that results from applying the relative path
 */
public static String applyRelativePath(String path, String relativePath) {
    try {
        // Split the paths into segments
        String[] pathSegments = path.split("/");
        String[] relativeSegments = relativePath.split("/");

        // Remove trailing slashes
        if (path.endsWith("/")) {
            path = path.substring(0, path.length() - 1);
        }
        if (relativePath.startsWith("/")) {
            relativePath = relativePath.substring(1);
        }

        // Apply the relative path segments
        for (String segment : relativeSegments) {
            if (segment.equals("..")) {
                if (pathSegments.length > 0) {
                    pathSegments = Arrays.copyOf(pathSegments, pathSegments.length - 1);
                }
            } else if (!segment.isEmpty()) {
                pathSegments = Arrays.copyOf(pathSegments, pathSegments.length + 1);
                pathSegments[pathSegments.length - 1] = segment;
            }
        }

        // Combine the segments back into a single path
        return String.join("/", pathSegments);
    } catch (Exception e) {
        // Handle exceptions, for example, empty paths
        return "";
    }
