public int readTag() throws IOException {
    // Read a single byte from the input stream
    int b = in.read();
    if (b == -1) {
        // If the end of the stream is reached, return zero
        return 0;
    }
    // Combine the first byte to form a tag
    int tag = b & 0x7f;
    // Check if the tag is a continuation tag
    while ((b & 0x80) != 0) {
        b = in.read();
        if (b == -1) {
            throw new IOException("Unexpected EOF while reading tag");
        }
        tag = (tag << 7) | (b & 0x7f);
    }
    return tag;
}
