 * @param start The starting byte position (inclusive).
 * @param end The ending byte position (inclusive).
 * @param totalLength The total length of the resource.
 * @return The 'Content-Range' value as a String, or null if input is invalid.
 */
private String buildContentRange(long start, long end, long totalLength) {
    if (start < 0 || end < 0 || totalLength < 0 || end < start || end > totalLength - 1) {
        return null; // Invalid input
    }
    if (totalLength == 0) {
        return "*/0"; // Empty resource
    }
    if (end == totalLength - 1) {
        return "bytes " + start + "-*/" + totalLength; // Range to end
    }
    return "bytes " + start + "-" + end + "/" + totalLength; // Specific range
}
